mapper.select:
/* Attd03Mapper.selectLeaves */ SELECT A.CMPNY_CD AS cmpnyCd , A.LEAVE_CD AS leaveCd , A.LEAVE_NO AS leaveNo , A.LEAVE_NM AS leaveNm , A.LEAVE_TYPE AS leaveType , FNC_CMM_INFO_SRCH(#{gvCmpnyCd}, 'SYST_VAL', A.LEAVE_TYPE, 'SYS021') AS leaveTypeNm , A.GRANT_TYPE AS grantType , FNC_CMM_INFO_SRCH(#{gvCmpnyCd}, 'SYST_VAL', A.GRANT_TYPE, 'SYS022') AS grantTypeNm , A.PAID_TYPE AS paidType , FNC_CMM_INFO_SRCH(#{gvCmpnyCd}, 'SYST_VAL', A.PAID_TYPE, 'SYS023') AS paidTypeNm , A.LEAVE_NATURE_TYPE AS leaveNatureType , FNC_CMM_INFO_SRCH(#{gvCmpnyCd}, 'SYST_VAL', A.LEAVE_NATURE_TYPE, 'SYS024') AS leaveNatureTypeNm , A.LEAVE_DAYS AS leaveDays , A.USE_UNIT_TYPE AS useUnitType , FNC_CMM_INFO_SRCH(#{gvCmpnyCd}, 'SYST_VAL', A.USE_UNIT_TYPE, 'SYS025') AS useUnitTypeNm , A.AVAIL_TERM_TYPE AS availTermType , FNC_CMM_INFO_SRCH(#{gvCmpnyCd}, 'SYST_VAL', A.AVAIL_TERM_TYPE, 'SYS026') AS availTermTypeNm , A.AVAIL_PERIOD AS availPeriod , A.USE_YN AS useYn , A.LEAVE_DESC AS leaveDesc , A.GRANT_BASE_TYPE AS grantBaseType , FNC_CMM_INFO_SRCH(#{gvCmpnyCd}, 'SYST_VAL', A.GRANT_BASE_TYPE, 'SYS027') AS grantBaseTypeNm , A.GRANT_OFFSET_MONTH AS grantOffsetMonth
, A.APRV_USE_YN AS aprvUseYn , A.APRV_STEP_CNT AS aprvStepCnt , A.HR_FINAL_APRV_YN AS hrFinalAprvYn , A.EVIDENCE_YN AS evidenceYn , A.EVIDENCE_GUIDE_MSG AS evidenceGuideMsg FROM ( SELECT A.CMPNY_CD , A.LEAVE_CD , A.LEAVE_NO , A.LEAVE_NM , A.LEAVE_TYPE , A.GRANT_TYPE , A.PAID_TYPE , A.LEAVE_NATURE_TYPE , CASE WHEN A.LEAVE_TYPE = '01' THEN A.MAX_APLY_DAYS WHEN A.LEAVE_TYPE = '02' THEN A.GRANT_DAYS END LEAVE_DAYS , A.USE_UNIT_TYPE , CASE WHEN A.LEAVE_TYPE = '01' THEN A.AVAIL_TERM_TYPE WHEN A.LEAVE_TYPE = '02' THEN A.ADMIN_AVAIL_TERM_TYPE END AVAIL_TERM_TYPE , CASE WHEN A.LEAVE_TYPE = '01' THEN CONCAT(A.AVAIL_FROM_DT, '~', A.AVAIL_TO_DT) WHEN A.LEAVE_TYPE = '02' THEN CONCAT(A.ADMIN_AVAIL_FROM_DT, '~', A.ADMIN_AVAIL_TO_DT) END AVAIL_PERIOD , A.USE_YN , A.LEAVE_DESC
, A.GRANT_BASE_TYPE , A.GRANT_OFFSET_MONTH
, A.APRV_USE_YN , A.APRV_STEP_CNT , A.HR_FINAL_APRV_YN , A.EVIDENCE_YN , A.EVIDENCE_GUIDE_MSG FROM TB_LEAVE_TYPE_MGMT A WHERE A.CMPNY_CD = #{gvCmpnyCd}
AND A.LEAVE_NO = #{leaveNo}
AND A.LEAVE_NM LIKE CONCAT('%', #{leaveNm}, '%')
AND A.LEAVE_TYPE = #{leaveType}
AND A.USE_YN = #{useYn}
) A

/* Attd03Mapper.selectLeaveNoDupChkResult */
SELECT 
	A.CMPNY_CD 		AS cmpnyCd
	, A.LEAVE_CD	AS leaveCd
	, A.LEAVE_NO	AS leaveNo
	, A.LEAVE_NM	AS leaveNm
FROM TB_LEAVE_TYPE_MGMT A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.LEAVE_NO = #{leaveNo}
LIMIT 1
